// SPDX-License-Identifier: GPL-2.0
/*
 * Copyright (C) 2019 Fredrik Noring
 */

#include <errno.h>
#include <string.h>
#include <stdlib.h>

#include "sndhfix/assert.h"
#include "sndhfix/compare.h"
#include "sndhfix/file.h"
#include "sndhfix/ice.h"
#include "sndhfix/memory.h"
#include "sndhfix/print.h"
#include "sndhfix/sndh.h"
#include "sndhfix/string.h"
#include "sndhfix/tool.h"
#include "sndhfix/unicode-atari-st.h"

struct tag {
	char *value;
	char buffer[32];

	int subtunes;
	bool hdns;

	bool (*cb)(const char *name, const char *value, void *arg);
	void *arg;

	bool continuation;
};

static size_t sndh_head_offset(struct file file)
{
	char *c = file.data;

	/*
	 * 20 bytes is the smallest possible header with "SNDH" at offset 12
	 * immediately followed by "HDNS".
	 */
	return file.size >= 20 &&
	       c[12] == 'S' &&
	       c[13] == 'N' &&
	       c[14] == 'D' &&
	       c[15] == 'H' ? 16 : 0;
}

static bool sndh_tag(const char *name, size_t *offset,
	size_t bound, struct file file)
{
	const size_t len = strlen(name);
	const char *c = file.data;

	if (*offset + len > bound)
		return false;
	if (strncmp(name, &c[*offset], len) != 0)
		return false;

	*offset += len;

	return true;
}

static void tag_cb(const char *name, const char *value, struct tag *tag)
{
	u8 *v = charset_to_utf8_string((const u8 *)value, strlen(value),
			charset_atari_st_to_utf32, NULL);

	tag->continuation = tag->cb(name, (const char *)v, tag->arg);

	free(v);
}

static bool sndh_nul(const char *name, size_t *offset,
	size_t bound, struct file file)
{
	const char *c = file.data;

	while (*offset < bound)
		if (c[(*offset)++] == '\0')
			return true;

	pr_warn("%s: tag %s missing NUL termination\n", file.path, name);

	return false;
}

static bool sndh_string__(const char *name, struct tag *tag, size_t length,
	size_t *offset, size_t bound, struct file file)
{
	char *c = file.data;

	if (!length) {
		tag->value = &c[*offset];

		if (!sndh_nul(name, offset, bound, file))
			return false;

		return true;
	}

	if (bound < *offset + length + 1)
		return false;

	BUG_ON(sizeof(tag->buffer) < length + 1);

	memcpy(tag->buffer, &c[*offset], length);
	tag->buffer[length] = 0;
	tag->value = tag->buffer;
	*offset += length;

	if (c[*offset] == '\0')
		(*offset)++;
	else
		pr_warn("%s: tag %s missing NUL termination\n",
			file.path, name);

	return true;
}

static bool sndh_string(const char *name, struct tag *tag, size_t length,
	size_t *offset, size_t bound, struct file file)
{
	if (!sndh_string__(name, tag, length, offset, bound, file))
		return false;

	tag_cb(name, tag->value, tag);

	return true;
}

static bool sndh_substrings(const char *name, struct tag *tag, size_t length,
	size_t *offset, size_t bound, struct file file)
{
	const size_t table_start = *offset - strlen(name);

	if (!tag->subtunes) {
		pr_warn("%s: tag %s without any subtunes\n", file.path, name);

		return true;
	}

	if (bound < *offset + tag->subtunes * 2) {
		pr_error("%s: tag %s too short\n", file.path, name);

		return false;
	}

	const u8 *b = file.data;
	const u8 *t = &b[*offset];

	*offset += tag->subtunes * 2;

	for (int i = 0; i < tag->subtunes; i++)
		if (!sndh_nul(name, offset, bound, file))
			return false;

	const size_t table_size = *offset - table_start;

	for (int i = 0; i < tag->subtunes && tag->continuation; i++) {
		const u16 o = (t[2 * i] << 8) | t[2 * i + 1];

		if (o < table_size) {
			tag_cb(name, (const char *)&b[table_start + o], tag);
		} else {
			pr_error("%s: tag %s table too short\n",
				file.path, name);

			return false;
		}
	}


	return true;
}

static bool sndh_integer(const char *name, struct tag *tag, size_t length,
	size_t *offset, size_t bound, struct file file)
{
	if (!sndh_string__(name, tag, length, offset, bound, file))
		return false;

	int n;

	if (!strtoint(&n, tag->value, 10)) {
		pr_warn("%s: tag %s malformed number: %s\n",
			file.path, name, tag->value);

		return false;
	}

	char s[32];
	snprintf(s, sizeof(s), "%d", n);
	tag_cb(name, s, tag);

	return true;
}

static bool sndh_subtunes(const char *name, struct tag *tag, size_t length,
	size_t *offset, size_t bound, struct file file)
{
	if (!sndh_string__(name, tag, length, offset, bound, file))
		return false;

	if (!strtoint(&tag->subtunes, tag->value, 10)) {
		pr_warn("%s: tag %s malformed number\n",
			file.path, name);

		return false;
	}

	char s[32];
	snprintf(s, sizeof(s), "%d", tag->subtunes);
	tag_cb(name, s, tag);

	return true;
}

static bool sndh_time(const char *name, struct tag *tag, size_t length,
	size_t *offset, size_t bound, struct file file)
{
	if (!tag->subtunes) {
		pr_warn("%s: tag %s without any subtunes\n", file.path, name);

		return true;
	}

	if (bound < *offset + tag->subtunes * 2) {
		pr_error("%s: tag %s too short\n", file.path, name);

		return false;
	}

	const u8 *b = file.data;
	for (int i = 0; i < tag->subtunes && tag->continuation; i++) {
		const u8 *t = &b[*offset + i * 2];
		const u16 n = (t[0] << 8) | t[1];
		char s[32];

		snprintf(s, sizeof(s), "%d", n);
		tag_cb(name, s, tag);
	}

	*offset += tag->subtunes * 2;

	return true;
}

static bool sndh_hdns(const char *name, struct tag *tag, size_t length,
	size_t *offset, size_t bound, struct file file)
{
	tag->hdns = true;

	return true;
}

static bool sndh_padding(const char *name, struct tag *tag, size_t length,
	size_t *offset, size_t bound, struct file file)
{
	char *c = file.data;

	if (*offset < file.size && c[*offset] == '\0') {
		(*offset)++;

		return true;
	}

	return false;
}

static void branch_bound(size_t *bound,
	size_t offset, const void *data, size_t size)
{
	const u8 *b = data;

	if (offset + size < 2)
		return;

	const u16 w = (b[offset + 0] << 8) | b[offset + 1];
	if (w == 0x4e71)	/* nop */
		return branch_bound(bound, offset + 2, data, size);

	if ((w & 0xff00) == 0x6000 && (w & 0xff) != 0) {	/* bra.s */
		const size_t a = offset + (w & 0xff);

		if (a < *bound)
			*bound = a;

		return;
	}

	if (offset + size < 4)
		return;

	if (w == 0x6000 ||	/* bra.w */
	    w == 0x4efa) {	/* jmp(pc) */
		const size_t a = offset + 2 +
			((b[offset + 2] << 8) | b[offset + 3]);

		if (a < *bound)
			*bound = a;

		return;
	}
}

static size_t tag_bound(struct file file)
{
	size_t bound = file.size;

	branch_bound(&bound, 0, file.data,  4);
	branch_bound(&bound, 4, file.data,  8);
	branch_bound(&bound, 8, file.data, 12);

	return bound;
}

static bool match_tag(struct tag *tag, size_t *offset,
	size_t bound, struct file file)
{
	static const struct {
		const char *name;
		bool (*read)(const char *name, struct tag *tag, size_t length,
			size_t *offset, size_t bound, struct file file);
		size_t length;
	} tags[] = {
		{ "TITL",  sndh_string      },
		{ "COMM",  sndh_string      },
		{ "RIPP",  sndh_string      },
		{ "CONV",  sndh_string      },
		{ "YEAR",  sndh_string      },
		{ "TA",    sndh_integer     },
		{ "TB",    sndh_integer     },
		{ "TC",    sndh_integer     },
		{ "TD",    sndh_integer     },
		{ "!#SN",  sndh_substrings  },
		{ "!#",    sndh_integer     },
		{ "!V",    sndh_integer     },
		{ "##",    sndh_subtunes, 2 },
		{ "TIME",  sndh_time        },
		{ "FLAG~", sndh_string      },
		{ "FLAG",  sndh_substrings  },
		{ "HDNS",  sndh_hdns        },
		{ "",      sndh_padding     }
	};

	for (size_t i = 0; i < ARRAY_SIZE(tags); i++)
		if (sndh_tag(tags[i].name, offset, bound, file) &&
		    tags[i].read(tags[i].name, tag,
				 tags[i].length, offset,
				 bound, file))
			return true;

	return false;
}

bool sndh_tags(struct file file, size_t *size, sndh_tag_cb cb, void *arg)
{
	size_t offset = sndh_head_offset(file);

	if (size)
		*size = 0;

	if (!offset) {
		pr_error("%s: invalid SNDH header\n", file.path);

		return false;
	}

	const size_t bound = tag_bound(file);
	struct tag tag = {
		.subtunes = 1,	/* Default to 1, unless the ## tag is given */
		.cb = cb,
		.arg = arg,
		.continuation = true
	};

	while (offset < bound && tag.continuation && !tag.hdns)
		if (!match_tag(&tag, &offset, bound, file)) {
			const u8 *b = file.data;

			pr_error("%s: unrecognised data in %zu bytes:\n",
				file.path, bound - offset);
			pr_mem(stderr, &b[offset],
				min(bound - offset, 256ul), offset);
			fprintf(stderr, "\n");

			if (size)
				*size = offset;

			return false;
		}

	if (size)
		*size = offset;

	if (tag.continuation && !tag.hdns)
		pr_warn("%s: missing HDNS tag\n", file.path);

	return tag.continuation;
}

struct file sndh_read_file(const char *path)
{
	struct file file = file_read_or_stdin(path);

	if (!file_valid(file))
		return file;

	if (ice_identify(file.data, file.size)) {
		const size_t s = ice_decrunched_size(file.data, file.size);
		void *b = xmalloc(s);

		if (ice_decrunch(b, file.data, file.size) == -1) {
			pr_error("%s: ICE decrunch failed\n", file.path);

			free(b);
			file_free(file);
			errno = ENOEXEC;

			return (struct file) { };
		}

		free(file.data);
		file.size = s;
		file.data = b;
	} else if (option_verbosity())
		pr_warn("%s: not ICE packed\n", file.path);

	return file;
}

johantibbelin-msa-inspector-src-msa-insp.text:
/*
 * msa_inspect.c — Atari ST MSA disk image tool
 *
 * Commands:
 *   msa_inspect [-v] [-d] [-l] <file.msa>          info (default)
 *   msa_inspect list <file.msa>                     list files
 *   msa_inspect extract <file.msa> [-o dir] [FILE…] extract files
 *   msa_inspect add <file.msa> <srcfile> [DEST]     add file to disk
 *
 * MSA header (10 bytes, big-endian):
 *   0x0E0F  magic
 *   uint16  sectors per track
 *   uint16  sides (0=single, 1=double)
 *   uint16  first track / last track
 *
 * Per track × side: uint16 stored-length, then that many bytes of data.
 * Raw when stored-length == spt×512; otherwise MSA RLE.
 * RLE: escape byte 0xE5, fill(1), count(2 big-endian).
 * A literal 0xE5 must be encoded as 0xE5 0xE5 0x00 0x01.
 *
 * The disk carries a FAT12 filesystem (MS-DOS compatible, little-endian).
 * Decompressing tracks in order gives a flat image; logical sector N is
 * at byte offset N × bytes_per_sector.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>
#include <ctype.h>
#include <time.h>
#include <errno.h>

#ifdef _WIN32
#  include <direct.h>
#  define portable_mkdir(p) _mkdir(p)
#else
#  include <sys/stat.h>
#  define portable_mkdir(p) mkdir((p), 0755)
#endif

/* ── constants ─────────────────────────────────────────────────────────── */

#define MSA_MAGIC        0x0E0Fu
#define MSA_ESCAPE       0xE5u
#define SECTOR_SIZE      512u
#define FAT_EOC          0xFF8u
#define MAX_DIR_DEPTH    16

#define DIR_ATTR_READONLY  0x01u
#define DIR_ATTR_HIDDEN    0x02u
#define DIR_ATTR_SYSTEM    0x04u
#define DIR_ATTR_VOLUME    0x08u
#define DIR_ATTR_DIR       0x10u
#define DIR_ATTR_ARCHIVE   0x20u
#define DIR_ATTR_LFN       0x0Fu

/* ── path helper ────────────────────────────────────────────────────────── */

/* Join two path components into dst[dstsize].  Returns dst, or NULL if it
 * would overflow (caller should skip the entry). */
static char *pjoin(char *dst, size_t dstsize, const char *a, const char *b)
{
    size_t la=strlen(a), lb=strlen(b);
    if (la+1+lb+1 > dstsize) return NULL;
    memcpy(dst,a,la); dst[la]='/'; memcpy(dst+la+1,b,lb+1);
    return dst;
}

/* ── byte-order helpers ─────────────────────────────────────────────────── */

static uint16_t be16(const uint8_t *p)
{ return (uint16_t)(((unsigned)p[0]<<8)|p[1]); }

static uint16_t le16(const uint8_t *p)
{ return (uint16_t)(p[0]|((unsigned)p[1]<<8)); }

static uint32_t le32(const uint8_t *p)
{ return (uint32_t)p[0]|((uint32_t)p[1]<<8)|
         ((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24); }

static void put_le16(uint8_t *p, uint16_t v) { p[0]=v&0xFF; p[1]=v>>8; }
static void put_le32(uint8_t *p, uint32_t v)
{ p[0]=v&0xFF; p[1]=(v>>8)&0xFF; p[2]=(v>>16)&0xFF; p[3]=(v>>24)&0xFF; }
static void put_be16(uint8_t *p, uint16_t v) { p[0]=v>>8; p[1]=v&0xFF; }

/* ── MSA RLE codec ──────────────────────────────────────────────────────── */

static int decompress_track(const uint8_t *in, size_t in_len,
                             uint8_t *out, size_t out_len)
{
    size_t i=0, o=0;
    while (i < in_len) {
        if (o >= out_len) {
            fprintf(stderr,"  RLE overflow at input %zu\n",i); return -1;
        }
        if (in[i] != MSA_ESCAPE) { out[o++]=in[i++]; continue; }
        if (i+3 >= in_len) {
            fprintf(stderr,"  RLE truncated at %zu\n",i); return -1;
        }
        uint8_t  fill  = in[i+1];
        uint16_t count = be16(&in[i+2]);
        i += 4;
        if (!count) continue;
        if (o+count > out_len) {
            fprintf(stderr,"  RLE run overflows\n"); return -1;
        }
        memset(out+o, fill, count);
        o += count;
    }
    return (int)o;
}

/* Returns compressed length; 0 means compressed >= raw (store raw instead). */
static size_t compress_track(const uint8_t *in, size_t in_len,
                              uint8_t *out, size_t out_cap)
{
    size_t o=0, i=0;
    while (i < in_len) {
        size_t run=1;
        while (i+run < in_len && run < 0xFFFFu && in[i+run]==in[i]) run++;
        int force = (in[i] == MSA_ESCAPE);
        if (force || run >= 5) {
            if (o+4 > out_cap) return 0;
            out[o++]=MSA_ESCAPE; out[o++]=in[i];
            out[o++]=(uint8_t)(run>>8); out[o++]=(uint8_t)(run&0xFF);
            i += run;
        } else {
            if (o+1 > out_cap) return 0;
            out[o++]=in[i++];
        }
    }
    return o;
}

/* ── MSA header + load/save ─────────────────────────────────────────────── */

typedef struct {
    uint16_t magic, spt, sides, t0, t1;
    int      num_sides, num_tracks;
    uint32_t track_bytes;
    uint64_t disk_bytes;
} MsaHdr;

static int msa_read_header(FILE *f, MsaHdr *h)
{
    uint8_t b[10];
    if (fread(b,1,10,f)!=10) { fputs("File too short\n",stderr); return -1; }
    h->magic = be16(b+0); h->spt  = be16(b+2);
    h->sides = be16(b+4); h->t0   = be16(b+6); h->t1 = be16(b+8);
    h->num_sides  = h->sides+1;
    h->num_tracks = (int)h->t1-(int)h->t0+1;
    h->track_bytes= (uint32_t)h->spt * SECTOR_SIZE;
    h->disk_bytes = (uint64_t)h->num_tracks * h->num_sides * h->track_bytes;
    return 0;
}

static uint8_t *msa_load(const char *path, MsaHdr *hdr)
{
    FILE *f = fopen(path,"rb");
    if (!f) { perror(path); return NULL; }
    if (msa_read_header(f,hdr)<0) { fclose(f); return NULL; }
    if (hdr->magic!=MSA_MAGIC || hdr->num_tracks<=0 || hdr->spt==0) {
        fprintf(stderr,"%s: invalid MSA header\n",path); fclose(f); return NULL;
    }

    uint8_t *image = calloc(1,(size_t)hdr->disk_bytes);
    if (!image) { perror("calloc"); fclose(f); return NULL; }

    uint8_t *cbuf=NULL; size_t cap=0;
    for (int t=hdr->t0; t<=hdr->t1; t++) {
        for (int s=0; s<hdr->num_sides; s++) {
            uint8_t lb[2];
            if (fread(lb,1,2,f)!=2) {
                fprintf(stderr,"EOF at track %d side %d\n",t,s); goto fail;
            }
            uint16_t dlen=be16(lb);
            if (dlen > cap) {
                free(cbuf); cbuf=malloc(dlen?dlen:1);
                if (!cbuf) { perror("malloc"); goto fail; }
                cap=dlen;
            }
            if (fread(cbuf,1,dlen,f)!=dlen) {
                fprintf(stderr,"EOF data track %d side %d\n",t,s); goto fail;
            }
            size_t off=((size_t)(t-hdr->t0)*hdr->num_sides+s)*hdr->track_bytes;
            if (dlen==hdr->track_bytes) {
                memcpy(image+off,cbuf,hdr->track_bytes);
            } else {
                int got=decompress_track(cbuf,dlen,image+off,hdr->track_bytes);
                if (got<0||(uint32_t)got!=hdr->track_bytes) {
                    fprintf(stderr,"Decomp error t%d s%d\n",t,s); goto fail;
                }
            }
        }
    }
    free(cbuf); fclose(f);
    return image;
fail:
    free(cbuf); free(image); fclose(f);
    return NULL;
}

static int msa_write(const char *path, const uint8_t *image, const MsaHdr *h)
{
    char tmp[512];
    snprintf(tmp,sizeof tmp,"%s.tmp~",path);
    FILE *f=fopen(tmp,"wb");
    if (!f) { perror(tmp); return -1; }

    uint8_t hb[10];
    put_be16(hb+0,h->magic); put_be16(hb+2,h->spt);
    put_be16(hb+4,h->sides); put_be16(hb+6,h->t0); put_be16(hb+8,h->t1);
    fwrite(hb,1,10,f);

    size_t cbuf_cap = (size_t)h->track_bytes*4+8;
    uint8_t *cbuf=malloc(cbuf_cap);
    if (!cbuf) { perror("malloc"); fclose(f); remove(tmp); return -1; }

    for (int t=h->t0; t<=h->t1; t++) {
        for (int s=0; s<h->num_sides; s++) {
            size_t off=((size_t)(t-h->t0)*h->num_sides+s)*h->track_bytes;
            const uint8_t *tr=image+off;
            size_t clen=compress_track(tr,h->track_bytes,cbuf,cbuf_cap);
            uint8_t lb[2];
            if (clen==0||clen>=h->track_bytes) {
                put_be16(lb,(uint16_t)h->track_bytes);
                fwrite(lb,1,2,f); fwrite(tr,1,h->track_bytes,f);
            } else {
                put_be16(lb,(uint16_t)clen);
                fwrite(lb,1,2,f); fwrite(cbuf,1,clen,f);
            }
        }
    }
    free(cbuf);
    if (fclose(f)!=0) { perror(tmp); remove(tmp); return -1; }
    if (rename(tmp,path)!=0) { perror("rename"); remove(tmp); return -1; }
    return 0;
}

/* ── disk geometry ──────────────────────────────────────────────────────── */

static const char *disk_geometry_name(uint16_t spt, int sides, int tracks)
{
    if (sides==1&&tracks==80&&spt== 9) return "SS/DD 360 KiB";
    if (sides==2&&tracks==80&&spt== 9) return "DS/DD 720 KiB";
    if (sides==2&&tracks==80&&spt==10) return "DS/DD 800 KiB";
    if (sides==2&&tracks==80&&spt==11) return "DS/DD 880 KiB";
    if (sides==2&&tracks==82&&spt== 9) return "DS/DD 738 KiB (82-track)";
    if (sides==2&&tracks==80&&spt==18) return "DS/HD 1.44 MiB";
    if (sides==2&&tracks==80&&spt==36) return "DS/ED 2.88 MiB";
    return "non-standard";
}

/* ── FAT12 ──────────────────────────────────────────────────────────────── */

typedef struct {
    uint8_t  *image;
    size_t    image_size;
    uint16_t  bytes_per_sector;
    uint8_t   sectors_per_cluster;
    uint8_t   num_fats;
    uint8_t  *fat;
    uint32_t  fat_size;
    size_t    root_dir_offset;
    uint32_t  root_dir_entries;
    size_t    root_dir_size;
    size_t    first_data_offset;
    uint32_t  cluster_size;
    uint32_t  total_clusters;
} FatFS;

static int fat_init(FatFS *fs, uint8_t *image, size_t image_size)
{
    memset(fs,0,sizeof *fs);
    if (image_size<512) return -1;
    const uint8_t *bs=image;
    uint16_t bps =le16(bs+11); uint8_t spc=bs[13];
    uint16_t rsvd=le16(bs+14); uint8_t nfat=bs[16];
    uint16_t rdent=le16(bs+17); uint16_t spf=le16(bs+22);
    if (!bps||!spc||!nfat||nfat>2||!rdent||!spf) return -1;
    size_t fat_off  =  (size_t)rsvd*bps;
    size_t root_off = fat_off+(size_t)nfat*spf*bps;
    size_t root_sz  = (size_t)rdent*32;
    size_t data_off = root_off+root_sz;
    if (fat_off>=image_size||root_off>=image_size||data_off>image_size) return -1;
    uint32_t fat_sz = (uint32_t)spf*bps;
    uint32_t csz    = (uint32_t)spc*bps;
    fs->image              = image;
    fs->image_size         = image_size;
    fs->bytes_per_sector   = bps;
    fs->sectors_per_cluster= spc;
    fs->num_fats           = nfat;
    fs->fat                = image+fat_off;
    fs->fat_size           = fat_sz;
    fs->root_dir_offset    = root_off;
    fs->root_dir_entries   = rdent;
    fs->root_dir_size      = root_sz;
    fs->first_data_offset  = data_off;
    fs->cluster_size       = csz;
    fs->total_clusters     = csz ? (uint32_t)((image_size-data_off)/csz) : 0;
    return 0;
}

static uint16_t fat12_get(const FatFS *fs, uint16_t c)
{
    uint32_t off=(uint32_t)c*3/2;
    if (off+1>=fs->fat_size) return 0xFFFu;
    uint16_t v=(uint16_t)(fs->fat[off]|((uint16_t)fs->fat[off+1]<<8));
    return (c&1)?(v>>4):(v&0x0FFFu);
}

static void fat12_set(FatFS *fs, uint16_t c, uint16_t val)
{
    uint32_t off=(uint32_t)c*3/2;
    if (off+1>=fs->fat_size) return;
    if (c&1) { fs->fat[off]=(fs->fat[off]&0x0F)|((val&0x0F)<<4); fs->fat[off+1]=(val>>4)&0xFF; }
    else     { fs->fat[off]=val&0xFF; fs->fat[off+1]=(fs->fat[off+1]&0xF0)|((val>>8)&0x0F); }
}

static void fat_sync(FatFS *fs)
{
    for (uint8_t i=1;i<fs->num_fats;i++)
        memcpy(fs->fat+(size_t)i*fs->fat_size,fs->fat,fs->fat_size);
}

static uint16_t fat_alloc_cluster(FatFS *fs)
{
    for (uint32_t i=2;i<fs->total_clusters+2;i++)
        if (fat12_get(fs,(uint16_t)i)==0) return (uint16_t)i;
    return 0;
}

static uint8_t *cluster_ptr(const FatFS *fs, uint16_t c)
{
    if (c<2) return NULL;
    size_t off=fs->first_data_offset+(size_t)(c-2)*fs->cluster_size;
    if (off+fs->cluster_size>fs->image_size) return NULL;
    return fs->image+off;
}

/* ── 8.3 filename ───────────────────────────────────────────────────────── */

static void from_83(const uint8_t *e, char *out)
{
    int n=0;
    for (int i=0;i<8&&e[i]!=' ';i++) out[n++]=(char)e[i];
    if (e[8]!=' ') { out[n++]='.'; for (int i=8;i<11&&e[i]!=' ';i++) out[n++]=(char)e[i]; }
    out[n]='\0';
    if ((unsigned char)out[0]==0x05) out[0]=(char)0xE5;
}

static int to_83(const char *name, uint8_t out[11])
{
    memset(out,' ',11);
    const char *dot=strrchr(name,'.');
    int nl=dot?(int)(dot-name):(int)strlen(name);
    if (nl==0||nl>8) return -1;
    for (int i=0;i<nl;i++) out[i]=(uint8_t)toupper((unsigned char)name[i]);
    if (dot) {
        int el=(int)strlen(dot+1);
        if (el>3) return -1;
        for (int i=0;i<el;i++) out[8+i]=(uint8_t)toupper((unsigned char)dot[1+i]);
    }
    return 0;
}

/* ── date / time ────────────────────────────────────────────────────────── */

static void format_datetime(uint16_t ft, uint16_t fd, char *buf, size_t n)
{
    snprintf(buf,n,"%04d-%02d-%02d %02d:%02d:%02d",
        1980+((fd>>9)&0x7F),(fd>>5)&0x0F,fd&0x1F,
        (ft>>11)&0x1F,(ft>>5)&0x3F,(ft&0x1F)*2);
}

static void now_fat(uint16_t *ft, uint16_t *fd)
{
    time_t now=time(NULL); struct tm *t=localtime(&now);
    *ft=(uint16_t)(((t->tm_hour&0x1F)<<11)|((t->tm_min&0x3F)<<5)|((t->tm_sec/2)&0x1F));
    *fd=(uint16_t)((((t->tm_year+1900-1980)&0x7F)<<9)|(((t->tm_mon+1)&0x0F)<<5)|(t->tm_mday&0x1F));
}

static void format_attrs(uint8_t a, char *buf)
{
    buf[0]=(a&DIR_ATTR_READONLY)?'R':'-'; buf[1]=(a&DIR_ATTR_HIDDEN)?'H':'-';
    buf[2]=(a&DIR_ATTR_SYSTEM)?'S':'-';   buf[3]=(a&DIR_ATTR_ARCHIVE)?'A':'-';
    buf[4]='\0';
}

/* ── directory helpers ──────────────────────────────────────────────────── */

/*
 * Returns 1 if e is a valid, non-deleted, non-LFN, non-volume directory entry.
 * Fills nm[13] with the formatted 8.3 name.
 */
static int entry_valid(const uint8_t *e, char nm[13])
{
    if (e[0]==0x00||(unsigned char)e[0]==0xE5) return 0;
    uint8_t a=e[11];
    if ((a&0x3Fu)==DIR_ATTR_LFN||a&DIR_ATTR_VOLUME) return 0;
    from_83(e,nm);
    return 1;
}

/*
 * Search one contiguous directory block for name11.
 * Returns pointer to the 32-byte entry, or NULL if not found.
 * Sets *hit_eod if a 0x00 terminator was seen (no more entries beyond).
 */
static uint8_t *search_block(uint8_t *data, size_t size,
                              const uint8_t name11[11], int *hit_eod)
{
    for (size_t o=0; o+32<=size; o+=32) {
        uint8_t *e=data+o;
        if (e[0]==0x00) { *hit_eod=1; return NULL; }
        if ((unsigned char)e[0]==0xE5) continue;
        uint8_t a=e[11];
        if ((a&0x3Fu)==DIR_ATTR_LFN||a&DIR_ATTR_VOLUME) continue;
        if (memcmp(e,name11,11)==0) return e;
    }
    return NULL;
}

/* Find a directory entry by 11-byte name; dir_cluster==0 means root dir. */
static uint8_t *dir_find(FatFS *fs, uint16_t dir_cluster, const uint8_t name11[11])
{
    int eod=0;
    uint8_t *found;
    if (dir_cluster==0) {
        found=search_block(fs->image+fs->root_dir_offset,fs->root_dir_size,name11,&eod);
        return found;
    }
    uint16_t c=dir_cluster; uint32_t g=0;
    while (c>=2&&c<FAT_EOC&&g++<4096) {
        uint8_t *cd=cluster_ptr(fs,c); if (!cd) break;
        found=search_block(cd,fs->cluster_size,name11,&eod);
        if (found) return found;
        if (eod) break;
        c=fat12_get(fs,c);
    }
    return NULL;
}

/*
 * Write a 32-byte entry into the directory at dir_cluster (0 = root dir).
 * Extends subdirectory cluster chain if all existing slots are used.
 * Returns 0 on success, -1 on failure.
 */
static int dir_add_entry(FatFS *fs, uint16_t dir_cluster, const uint8_t entry[32])
{
    if (dir_cluster==0) {
        uint8_t *rd=fs->image+fs->root_dir_offset;
        for (size_t o=0; o+32<=fs->root_dir_size; o+=32) {
            if (rd[o]==0x00||(unsigned char)rd[o]==0xE5) {
                memcpy(rd+o,entry,32);
                if (o+64<=fs->root_dir_size) rd[o+32]=0x00;
                return 0;
            }
        }
        return -1;
    }
    uint16_t c=dir_cluster, prev=0; uint32_t g=0;
    while (c>=2&&c<FAT_EOC&&g++<4096) {
        uint8_t *cd=cluster_ptr(fs,c);
        if (!cd) break;
        for (uint32_t o=0; o+32<=fs->cluster_size; o+=32) {
            if (cd[o]==0x00||(unsigned char)cd[o]==0xE5) {
                memcpy(cd+o,entry,32);
                if (o+64<=fs->cluster_size) cd[o+32]=0x00;
                return 0;
            }
        }
        prev=c; c=fat12_get(fs,c);
    }
    if (!prev) return -1;
    uint16_t nc=fat_alloc_cluster(fs);
    if (!nc) return -1;
    fat12_set(fs,prev,nc); fat12_set(fs,nc,0xFFFu);
    uint8_t *cd=cluster_ptr(fs,nc);
    if (!cd) return -1;
    memset(cd,0,fs->cluster_size);
    memcpy(cd,entry,32);
    return 0;
}

/* ── path navigation ────────────────────────────────────────────────────── */

/*
 * Resolves "GAMES/PONG.TOS" into:
 *   *parent_out  = cluster of the containing directory (0 = root)
 *   name11[11]   = 8.3 name of the final path component
 * Returns 0 on success.
 */
static int path_split(FatFS *fs, const char *path,
                      uint16_t *parent_out, uint8_t name11[11])
{
    char buf[512];
    strncpy(buf,path,511); buf[511]='\0';
    for (char *p=buf;*p;p++) if(*p=='\\') *p='/';

    char *slash=strrchr(buf,'/');
    char *filename, *dirpart;
    if (slash) { *slash='\0'; filename=slash+1; dirpart=buf; }
    else        { filename=buf; dirpart=NULL; }

    if (to_83(filename,name11)<0) {
        fprintf(stderr,"'%s': not a valid 8.3 filename\n",filename); return -1;
    }
    uint16_t cluster=0;
    if (dirpart&&*dirpart) {
        char *comp=strtok(dirpart,"/");
        while (comp) {
            uint8_t n11[11];
            if (to_83(comp,n11)<0) {
                fprintf(stderr,"'%s': not a valid 8.3 name\n",comp); return -1;
            }
            uint8_t *e=dir_find(fs,cluster,n11);
            if (!e||!(e[11]&DIR_ATTR_DIR)) {
                fprintf(stderr,"Directory '%s' not found\n",comp); return -1;
            }
            cluster=le16(e+26);
            comp=strtok(NULL,"/");
        }
    }
    *parent_out=cluster;
    return 0;
}

/* ── file I/O ───────────────────────────────────────────────────────────── */

static uint8_t *fat_read_file(const FatFS *fs, uint16_t start, uint32_t size)
{
    if (!size) return calloc(1,1);
    uint8_t *buf=malloc(size);
    if (!buf) { perror("malloc"); return NULL; }
    size_t done=0; uint16_t c=start;
    while (c>=2&&c<FAT_EOC&&done<size) {
        const uint8_t *cd=cluster_ptr(fs,c); if (!cd) break;
        size_t chunk=size-done<fs->cluster_size?(size_t)(size-done):fs->cluster_size;
        memcpy(buf+done,cd,chunk); done+=chunk;
        c=fat12_get(fs,c);
    }
    return buf;
}

static int fat_add_file(FatFS *fs, uint16_t dir_cluster,
                        const uint8_t name11[11],
                        const uint8_t *data, uint32_t size)
{
    if (dir_find(fs,dir_cluster,name11)) {
        char nm[13]; from_83(name11,nm);
        fprintf(stderr,"'%s' already exists on disk\n",nm); return -1;
    }
    uint32_t ncl=size==0?0:(size+fs->cluster_size-1)/fs->cluster_size;
    uint16_t first=0, prev=0;
    for (uint32_t i=0;i<ncl;i++) {
        uint16_t c=fat_alloc_cluster(fs);
        if (!c) { fprintf(stderr,"Disk full\n"); return -1; }
        fat12_set(fs,c,0xFFFu);
        if (prev) fat12_set(fs,prev,c); else first=c;
        uint8_t *cd=cluster_ptr(fs,c); if (!cd) return -1;
        size_t base=(size_t)i*fs->cluster_size;
        size_t chunk=((size_t)size-base)<fs->cluster_size?(size_t)size-base:fs->cluster_size;
        memcpy(cd,data+base,chunk);
        if (chunk<fs->cluster_size) memset(cd+chunk,0,fs->cluster_size-chunk);
        prev=c;
    }
    uint8_t ent[32]; memset(ent,0,32);
    memcpy(ent,name11,11); ent[11]=DIR_ATTR_ARCHIVE;
    uint16_t ft,fd; now_fat(&ft,&fd);
    put_le16(ent+22,ft); put_le16(ent+24,fd);
    put_le16(ent+26,first); put_le32(ent+28,size);
    if (dir_add_entry(fs,dir_cluster,ent)<0) {
        fprintf(stderr,"Directory full\n"); return -1;
    }
    fat_sync(fs);
    return 0;
}

/* ── directory listing ──────────────────────────────────────────────────── */

/* forward declaration */
static void list_dir(FatFS *fs, uint16_t dir_cluster, int is_root,
                     const char *prefix, int depth);

static void list_dir_block(FatFS *fs, uint8_t *data, size_t size,
                           const char *prefix, int depth)
{
    for (size_t o=0; o+32<=size; o+=32) {
        uint8_t *e=data+o;
        char nm[13];
        if (!entry_valid(e,nm)) { if (e[0]==0x00) return; continue; }
        if (nm[0]=='.') continue;

        char path[512]; snprintf(path,sizeof path,"%s%s",prefix,nm);
        char dt[20];    format_datetime(le16(e+22),le16(e+24),dt,sizeof dt);
        char as[5];     format_attrs(e[11],as);

        if (e[11]&DIR_ATTR_DIR) {
            printf("  %-36s  %-8s  %s  %s\n",path,"<DIR>",dt,as);
            char np[4096]; snprintf(np,sizeof np,"%s%s/",prefix,nm);
            list_dir(fs,le16(e+26),0,np,depth+1);
        } else {
            char szbuf[16]; snprintf(szbuf,sizeof szbuf,"%" PRIu32,le32(e+28));
            printf("  %-36s  %8s  %s  %s\n",path,szbuf,dt,as);
        }
    }
}

static void list_dir(FatFS *fs, uint16_t dir_cluster, int is_root,
                     const char *prefix, int depth)
{
    if (depth>MAX_DIR_DEPTH) { fprintf(stderr,"Max depth reached\n"); return; }
    if (is_root) {
        list_dir_block(fs,fs->image+fs->root_dir_offset,fs->root_dir_size,prefix,depth);
    } else {
        uint16_t c=dir_cluster; uint32_t g=0;
        while (c>=2&&c<FAT_EOC&&g++<4096) {
            uint8_t *cd=cluster_ptr(fs,c); if (!cd) break;
            list_dir_block(fs,cd,fs->cluster_size,prefix,depth);
            c=fat12_get(fs,c);
        }
    }
}

static void list_filesystem(FatFS *fs)
{
    const uint8_t *bs=fs->image;
    uint16_t spf=le16(bs+22);

    char vol[12]="";
    uint8_t *rd=fs->image+fs->root_dir_offset;
    for (size_t o=0; o+32<=fs->root_dir_size; o+=32) {
        if (rd[o]==0x00) break;
        if ((unsigned char)rd[o]==0xE5) continue;
        if (rd[o+11]&DIR_ATTR_VOLUME) {
            memcpy(vol,rd+o,11); vol[11]='\0';
            for (int i=10;i>=0&&vol[i]==' ';i--) vol[i]='\0';
            break;
        }
    }
    printf("\n=== Filesystem ===\n");
    printf("Volume label  : %s\n",vol[0]?vol:"(none)");
    printf("FAT type      : FAT12\n");
    printf("Bytes/sector  : %u\n",fs->bytes_per_sector);
    printf("Sectors/clust : %u (%u bytes/cluster)\n",
           fs->sectors_per_cluster,fs->cluster_size);
    printf("FAT copies    : %u (%u sectors each)\n",fs->num_fats,spf);
    printf("Root entries  : %u\n",fs->root_dir_entries);
    printf("Data clusters : %u\n",fs->total_clusters);
    printf("\n  %-36s  %8s  %-19s  %s\n","Name","Size","Modified","Attr");
    printf("  %-36s  %8s  %-19s  %s\n",
           "------------------------------------","--------",
           "-------------------","----");
    list_dir(fs,0,1,"",0);
}

/* ── extract ─────────────────────────────────────────────────────────────── */

static void mkdirs(const char *path)
{
    char buf[512]; strncpy(buf,path,511); buf[511]='\0';
    for (char *p=buf+1;*p;p++) { if(*p=='/'){*p='\0';portable_mkdir(buf);*p='/';} }
    portable_mkdir(buf);
}

static int write_host_file(const char *out_path, const uint8_t *data, uint32_t size)
{
    FILE *fout=fopen(out_path,"wb");
    if (!fout) { perror(out_path); return -1; }
    if (size) fwrite(data,1,size,fout);
    fclose(fout);
    printf("  extracted  %s  (%" PRIu32 " bytes)\n",out_path,size);
    return 0;
}

/* forward declaration */
static void extract_dir(FatFS *fs, uint16_t dir_cluster, int is_root,
                        const char *out_base, const char *rel_prefix, int depth);

static void extract_dir_block(FatFS *fs, uint8_t *data, size_t size,
                              const char *out_base, const char *rel_prefix, int depth)
{
    for (size_t o=0; o+32<=size; o+=32) {
        uint8_t *e=data+o;
        char nm[13];
        if (!entry_valid(e,nm)) { if (e[0]==0x00) return; continue; }
        if (nm[0]=='.') continue;

        /* Build relative path: rel_prefix + nm, and full host path: out_base/rel */
        size_t rpl=strlen(rel_prefix), nml=strlen(nm);
        char rel[4096];
        if (rpl+nml+1 > sizeof rel) continue;
        memcpy(rel,rel_prefix,rpl); memcpy(rel+rpl,nm,nml+1);
        char full[4096];
        if (!pjoin(full,sizeof full,out_base,rel)) continue;

        if (e[11]&DIR_ATTR_DIR) {
            mkdirs(full);
            char np[4096];
            if (rpl+nml+2 > sizeof np) continue;
            memcpy(np,rel_prefix,rpl); memcpy(np+rpl,nm,nml); np[rpl+nml]='/'; np[rpl+nml+1]='\0';
            extract_dir(fs,le16(e+26),0,out_base,np,depth+1);
        } else {
            uint32_t fsz=le32(e+28);
            uint8_t *buf=fat_read_file(fs,le16(e+26),fsz);
            if (!buf) continue;
            write_host_file(full,buf,fsz);
            free(buf);
        }
    }
}

static void extract_dir(FatFS *fs, uint16_t dir_cluster, int is_root,
                        const char *out_base, const char *rel_prefix, int depth)
{
    if (depth>MAX_DIR_DEPTH) return;
    if (is_root) {
        extract_dir_block(fs,fs->image+fs->root_dir_offset,fs->root_dir_size,
                          out_base,rel_prefix,depth);
    } else {
        uint16_t c=dir_cluster; uint32_t g=0;
        while (c>=2&&c<FAT_EOC&&g++<4096) {
            uint8_t *cd=cluster_ptr(fs,c); if (!cd) break;
            extract_dir_block(fs,cd,fs->cluster_size,out_base,rel_prefix,depth);
            c=fat12_get(fs,c);
        }
    }
}

/* Extract a single named file from the disk to out_dir. */
static int extract_one(FatFS *fs, const char *msa_path, const char *out_dir)
{
    char buf[512]; strncpy(buf,msa_path,511); buf[511]='\0';
    for (char *p=buf;*p;p++) if(*p=='\\') *p='/';

    uint16_t dir_cluster=0;
    char *slash=strrchr(buf,'/');
    char *filename;
    if (slash) {
        *slash='\0'; filename=slash+1;
        char *comp=strtok(buf,"/");
        while (comp) {
            uint8_t n11[11];
            if (to_83(comp,n11)<0) { fprintf(stderr,"Bad path '%s'\n",comp); return -1; }
            uint8_t *e=dir_find(fs,dir_cluster,n11);
            if (!e||!(e[11]&DIR_ATTR_DIR)) {
                fprintf(stderr,"Directory '%s' not found\n",comp); return -1;
            }
            dir_cluster=le16(e+26);
            comp=strtok(NULL,"/");
        }
    } else { filename=buf; }

    uint8_t name11[11];
    if (to_83(filename,name11)<0) {
        fprintf(stderr,"'%s': not a valid 8.3 filename\n",filename); return -1;
    }
    uint8_t *e=dir_find(fs,dir_cluster,name11);
    if (!e) { fprintf(stderr,"'%s' not found on disk\n",msa_path); return -1; }
    if (e[11]&DIR_ATTR_DIR) {
        fprintf(stderr,"'%s' is a directory\n",msa_path); return -1;
    }
    uint32_t fsz=le32(e+28);
    uint8_t *data=fat_read_file(fs,le16(e+26),fsz);
    if (!data) return -1;

    char out_path[4096]; snprintf(out_path,sizeof out_path,"%s/%s",out_dir,filename);
    int ret=write_host_file(out_path,data,fsz);
    free(data);
    return ret;
}

/* ── commands ────────────────────────────────────────────────────────────── */

static int cmd_info(const char *path, int verbose, int validate, int do_list)
{
    FILE *f=fopen(path,"rb");
    if (!f) { perror(path); return 1; }

    MsaHdr h;
    if (msa_read_header(f,&h)<0) { fclose(f); return 1; }

    printf("File     : %s\n",path);
    if (h.magic!=MSA_MAGIC)
        printf("Magic    : 0x%04X  WARNING: expected 0x%04X\n",h.magic,MSA_MAGIC);
    else
        printf("Magic    : 0x%04X  OK\n",h.magic);
    printf("Geometry : %u sectors/track, %d side%s, tracks %u-%u (%d tracks)\n",
           h.spt,h.num_sides,h.num_sides>1?"s":"",h.t0,h.t1,h.num_tracks);
    printf("Format   : %s\n",disk_geometry_name(h.spt,h.num_sides,h.num_tracks));
    printf("Capacity : %" PRIu64 " bytes  (%.1f KiB)\n",h.disk_bytes,h.disk_bytes/1024.0);

    if (h.magic!=MSA_MAGIC||h.num_tracks<=0||h.spt==0) {
        fputs("Aborting — invalid header\n",stderr); fclose(f); return 1;
    }
    if (verbose||validate)
        puts("\nTrack  Side  Stored   Raw      Saving  Status\n"
             "-----  ----  -------  -------  ------  ------");

    uint8_t *cbuf=NULL; size_t cap=0;
    uint8_t *ubuf = (validate&&!do_list) ? malloc(h.track_bytes) : NULL;
    uint8_t *image= do_list ? calloc(1,(size_t)h.disk_bytes) : NULL;
    int errors=0; uint64_t stored=0; int compr=0;
    int total=h.num_tracks*h.num_sides;

    for (int t=h.t0; t<=h.t1; t++) {
        for (int s=0; s<h.num_sides; s++) {
            uint8_t lb[2];
            if (fread(lb,1,2,f)!=2) {
                fprintf(stderr,"EOF t%d s%d\n",t,s); errors++; goto done;
            }
            uint16_t dlen=be16(lb);
            if (dlen>cap) {
                free(cbuf); cbuf=malloc(dlen?dlen:1);
                if (!cbuf){errors++;goto done;} cap=dlen;
            }
            if (fread(cbuf,1,dlen,f)!=dlen) {
                fprintf(stderr,"EOF data t%d s%d\n",t,s); errors++; goto done;
            }
            int compressed=(dlen!=h.track_bytes);
            stored+=dlen; if(compressed)compr++;
            size_t off=((size_t)(t-h.t0)*h.num_sides+s)*h.track_bytes;
            const char *status="raw";
            if (!compressed) {
                if (image) memcpy(image+off,cbuf,h.track_bytes);
            } else if (image) {
                int got=decompress_track(cbuf,dlen,image+off,h.track_bytes);
                if (got<0||(uint32_t)got!=h.track_bytes){status="DECOMP ERROR";errors++;}
                else status="ok";
            } else if (validate) {
                int got=decompress_track(cbuf,dlen,ubuf,h.track_bytes);
                if (got<0||(uint32_t)got!=h.track_bytes){status="DECOMP ERROR";errors++;}
                else status="ok";
            } else { status="compressed"; }
            if (verbose||validate)
                printf("  %3d    %d  %6u   %6u   %5.1f%%  %s\n",
                       t,s,dlen,h.track_bytes,
                       compressed?100.0*(1.0-(double)dlen/h.track_bytes):0.0,status);
        }
    }
    { long p=ftell(f); fseek(f,0,SEEK_END); long e=ftell(f);
      if(e-p>0) printf("WARNING: %ld trailing byte%s\n",e-p,e-p==1?"":"s"); }
done:
    printf("\nSummary\n");
    printf("  Compressed tracks : %d / %d (%.0f%%)\n",compr,total,
           total?100.0*compr/total:0.0);
    printf("  File data size    : %" PRIu64 " bytes  (%.1f KiB)\n",stored,stored/1024.0);
    printf("  Uncompressed size : %" PRIu64 " bytes  (%.1f KiB)\n",h.disk_bytes,h.disk_bytes/1024.0);
    if (h.disk_bytes)
        printf("  Overall saving    : %.1f%%\n",100.0*(1.0-(double)stored/h.disk_bytes));
    printf("  Errors            : %d\n",errors);

    if (do_list&&image&&!errors&&h.t0==0) {
        FatFS fs;
        if (fat_init(&fs,image,(size_t)h.disk_bytes)==0) list_filesystem(&fs);
        else puts("\nNo valid FAT12 filesystem found");
    } else if (do_list&&h.t0!=0) {
        puts("\nNote: listing skipped — image does not start at track 0");
    }
    free(cbuf); free(ubuf); free(image); fclose(f);
    return errors?1:0;
}

static int cmd_list(const char *path)
{
    MsaHdr h; uint8_t *image=msa_load(path,&h);
    if (!image) return 1;
    if (h.t0!=0) { puts("Image does not start at track 0"); free(image); return 1; }
    FatFS fs;
    if (fat_init(&fs,image,(size_t)h.disk_bytes)<0) {
        puts("No valid FAT12 filesystem found"); free(image); return 1;
    }
    list_filesystem(&fs);
    free(image); return 0;
}

static int cmd_extract(const char *msa_path, const char *out_dir,
                       char **files, int nfiles)
{
    MsaHdr h; uint8_t *image=msa_load(msa_path,&h);
    if (!image) return 1;
    FatFS fs;
    if (fat_init(&fs,image,(size_t)h.disk_bytes)<0) {
        puts("No valid FAT12 filesystem found"); free(image); return 1;
    }
    mkdirs(out_dir);
    int ret=0;
    if (nfiles==0) {
        extract_dir(&fs,0,1,out_dir,"",0);
    } else {
        for (int i=0;i<nfiles;i++) ret|=extract_one(&fs,files[i],out_dir);
    }
    free(image); return ret;
}

static int cmd_add(const char *msa_path, const char *src_path, const char *dest)
{
    FILE *sf=fopen(src_path,"rb");
    if (!sf) { perror(src_path); return 1; }
    fseek(sf,0,SEEK_END); long fsz=ftell(sf); rewind(sf);
    if (fsz<0) { perror("ftell"); fclose(sf); return 1; }
    uint8_t *data=NULL;
    if (fsz>0) {
        data=malloc((size_t)fsz);
        if (!data) { perror("malloc"); fclose(sf); return 1; }
        if ((long)fread(data,1,(size_t)fsz,sf)!=fsz) {
            perror(src_path); free(data); fclose(sf); return 1;
        }
    }
    fclose(sf);

    /* Determine name on disk */
    const char *dst=dest?dest:src_path;
    if (!dest) {
        const char *sl=strrchr(dst,'/');
        if (!sl) sl=strrchr(dst,'\\');
        if (sl) dst=sl+1;
    }

    MsaHdr h; uint8_t *image=msa_load(msa_path,&h);
    if (!image) { free(data); return 1; }
    FatFS fs;
    if (fat_init(&fs,image,(size_t)h.disk_bytes)<0) {
        puts("No valid FAT12 filesystem found"); free(data); free(image); return 1;
    }

    uint16_t parent; uint8_t name11[11];
    if (path_split(&fs,dst,&parent,name11)<0) {
        free(data); free(image); return 1;
    }
    if (fat_add_file(&fs,parent,name11,data,(uint32_t)fsz)<0) {
        free(data); free(image); return 1;
    }
    free(data);

    char nm[13]; from_83(name11,nm);
    printf("Added '%s' (%ld bytes) to disk image\n",nm,fsz);

    int ret=msa_write(msa_path,image,&h);
    free(image);
    return ret<0?1:0;
}

/* ── usage & main ────────────────────────────────────────────────────────── */

static void usage(const char *p)
{
    fprintf(stderr,
        "Usage:\n"
        "  %s [-v] [-d] [-l] <file.msa>               show disk info\n"
        "  %s list <file.msa>                           list files on disk\n"
        "  %s extract <file.msa> [-o dir] [FILE…]      extract (all if none given)\n"
        "  %s add <file.msa> <srcfile> [DEST]           add file to disk image\n"
        "\nFlags for info:\n"
        "  -v  per-track verbose output\n"
        "  -d  decompress and validate each track\n"
        "  -l  list filesystem after info\n"
        "  -h  show this help\n",
        p,p,p,p);
}

int main(int argc, char *argv[])
{
    if (argc<2) { usage(argv[0]); return 1; }

    if (strcmp(argv[1],"list")==0) {
        if (argc<3) { fprintf(stderr,"Usage: %s list <file.msa>\n",argv[0]); return 1; }
        return cmd_list(argv[2]);
    }
    if (strcmp(argv[1],"extract")==0) {
        if (argc<3) { fprintf(stderr,"Usage: %s extract <file.msa> [-o dir] [FILE…]\n",argv[0]); return 1; }
        const char *msa=argv[2], *outdir=".";
        int first=3;
        if (argc>=5&&strcmp(argv[3],"-o")==0) { outdir=argv[4]; first=5; }
        return cmd_extract(msa,outdir,argv+first,argc-first);
    }
    if (strcmp(argv[1],"add")==0) {
        if (argc<4) { fprintf(stderr,"Usage: %s add <file.msa> <srcfile> [DEST]\n",argv[0]); return 1; }
        return cmd_add(argv[2],argv[3],argc>=5?argv[4]:NULL);
    }

    /* Default: info */
    int verbose=0, validate=0, list=0, file_args=0, ret=0;
    for (int i=1;i<argc;i++) {
        if (argv[i][0]=='-'&&argv[i][1]) {
            for (int j=1;argv[i][j];j++) switch(argv[i][j]) {
                case 'v': verbose=1;  break;
                case 'd': validate=1; break;
                case 'l': list=1;     break;
                case 'h': usage(argv[0]); return 0;
                default: fprintf(stderr,"Unknown option: -%c\n",argv[i][j]); return 1;
            }
        } else {
            if (file_args++>0) putchar('\n');
            ret|=cmd_info(argv[i],verbose,validate,list);
        }
    }
    if (!file_args) { usage(argv[0]); return 1; }
    return ret;
}
